"""Private file storage on the local filesystem.

Files are saved under randomly generated keys, never under user-supplied names,
and are only ever served through authorised API endpoints.
"""

import secrets
from pathlib import Path

from app.core.config import get_settings


def _root() -> Path:
    root = get_settings().storage_dir
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def _resolve(key: str) -> Path:
    path = (_root() / key).resolve()
    # Keys are generated by us, but refuse anything that escapes the storage root.
    if _root() not in path.parents:
        raise ValueError("Invalid storage key")
    return path


def save(folder: str, extension: str, data: bytes) -> str:
    """Store bytes and return the storage key."""
    key = f"{folder}/{secrets.token_hex(16)}{extension}"
    path = _resolve(key)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    return key


def path_for(key: str) -> Path:
    path = _resolve(key)
    if not path.is_file():
        raise FileNotFoundError(key)
    return path


def delete(key: str) -> None:
    try:
        _resolve(key).unlink(missing_ok=True)
    except (OSError, ValueError):
        # A missing file must not block deleting its database record.
        pass
